77	fn parse_definition(p: &mut GraphqlParser) -> ParsedSyntax {
78	    let keyword = if is_at_string(p) { p.nth(1) } else { p.cur() };
79	    match keyword {
80	        T![query] | T![mutation] | T![subscription] => parse_operation_definition(p),
81	        T!['{'] => parse_selection_set(p),
82	        T![fragment] => parse_fragment_definition(p),
83	        T![schema] => parse_schema_definition(p),
84	        T![scalar] => parse_scalar_type_definition(p),
85	        T![type] => parse_object_type_definition(p),
86	        T![interface] => parse_interface_type_definition(p),
87	        T![union] => parse_union_type_definition(p),
88	        T![enum] => parse_enum_type_definition(p),
89	        T![input] => parse_input_object_type_definition(p),
90	        T![directive] => parse_directive_definition(p),
91	        T![extend] => parse_extension(p),
92	        _ => Absent,
93	    }
94	}
