impl From<u16> for GraphqlSyntaxKind {
    fn from(d: u16) -> GraphqlSyntaxKind {
        assert!(d <= (GraphqlSyntaxKind::__LAST as u16));
        unsafe { std::mem::transmute::<u16, GraphqlSyntaxKind>(d) }
    }
}

impl From<GraphqlSyntaxKind> for u16 {
